"function model
% Short-period identification from sampled flight data (id_02)
dt = 0.02;

N = size(X,1);
Phi = [X(1:end-1,:), u(1:end-1)];
Y  = X(2:end,:);
Theta = Phi\Y;                 % least squares (rows: [Ad Bd])
Ad = Theta(1:4,:)';
Bd = Theta(5,:)';

lam = eig(Ad);
s = log(lam)/dt;

% pick short-period pair: complex pair with largest |s|
cands = s(abs(imag(s))>1e-6);
[~,idx] = max(abs(cands));
s_sp = cands(idx);

omega_sp_id = abs(s_sp);
zeta_sp_id = -real(s_sp)/omega_sp_id;

result = struct('omega_sp_id', omega_sp_id, 'zeta_sp_id', zeta_sp_id);
fid = fopen('result.json','w');
fwrite(fid, jsonencode(result));
fclose(fid);
fprintf('omega_sp_id = %.6f rad/s, zeta_sp_id = %.6f\n', omega_sp_id, zeta_sp_id);
end"

